using System.Collections.Concurrent;
using Mono.Cecil;

/// <summary>
/// Forces Mono.Cecil to eagerly read the lazily-loaded parts of types.
/// </summary>
/// <remarks>
/// Mono.Cecil reads metadata lazily and every lazy read takes a lock on the
/// module. Since the projection is generated by many threads in parallel that
/// all read from the same module, the lock contention is severe. Reading
/// the metadata for a namespace up front on a single thread before handing
/// it off for generation makes the subsequent reads lock-free.
///
/// Also, the <c>Has*</c> properties of Mono.Cecil objects take the lock on
/// every call until the corresponding collection has been read, so this
/// touches the collections themselves rather than using the <c>Has*</c>
/// properties.
///
/// This is purely an optimization. Anything that is not preloaded here is
/// still read lazily when it is needed.
/// </remarks>
sealed class ModulePreloader
{
    private readonly HashSet<TypeDefinition> visited = new(ReferenceEqualityComparer.Instance);

    // NB: Mono.Cecil takes the module lock on every access to
    // PropertyDefinition.SetMethod when the property doesn't have a setter,
    // so we remember the result here to avoid that.
    private static readonly ConcurrentDictionary<PropertyDefinition, MethodDefinition?> setMethods =
        new(Environment.ProcessorCount * 4, 1 << 15, ReferenceEqualityComparer.Instance);

    /// <summary>
    /// Gets the set method of <paramref name="property"/> without taking
    /// the module lock if the property has already been preloaded.
    /// </summary>
    public static MethodDefinition? GetSetMethod(PropertyDefinition property) =>
        setMethods.TryGetValue(property, out var setMethod) ? setMethod : property.SetMethod;

    /// <summary>
    /// Preloads <paramref name="types"/> along with the interfaces they
    /// implement, the types they derive from and their factory interfaces.
    /// </summary>
    public void Preload(IEnumerable<TypeDefinition> types)
    {
        foreach (var type in types)
        {
            PreloadClosure(type);
        }
    }

    private void PreloadClosure(TypeDefinition type)
    {
        if (!visited.Add(type))
        {
            return;
        }

        PreloadType(type);

        foreach (var iface in type.Interfaces)
        {
            if (iface.InterfaceType.TryResolve() is TypeDefinition resolved)
            {
                PreloadClosure(resolved);
            }
        }

        if (type.BaseType?.TryResolve() is TypeDefinition baseType)
        {
            PreloadClosure(baseType);
        }

        foreach (var attr in type.CustomAttributes)
        {
            if (
                attr.AttributeType.Namespace == "Windows.Foundation.Metadata"
                && attr.AttributeType.Name
                    is "ActivatableAttribute"
                        or "StaticAttribute"
                        or "ComposableAttribute"
            )
            {
                foreach (var arg in attr.ConstructorArguments)
                {
                    if (
                        arg.Type.FullName == "System.Type"
                        && arg.Value is TypeReference factoryType
                        && factoryType.TryResolve() is TypeDefinition resolved
                    )
                    {
                        PreloadClosure(resolved);
                    }
                }
            }
        }
    }

    private static void PreloadType(TypeDefinition type)
    {
        // NB: only the things that are actually used by the code generator
        // are preloaded here, e.g. custom attributes of fields, properties
        // and events are not used.

        PreloadCustomAttributes(type);
        _ = type.GenericParameters;

        foreach (var iface in type.Interfaces)
        {
            PreloadCustomAttributes(iface);
        }

        if (type.IsEnum)
        {
            foreach (var field in type.Fields)
            {
                _ = field.Constant;
            }
        }
        else
        {
            _ = type.Fields;
        }

        foreach (var method in type.Methods)
        {
            PreloadCustomAttributes(method);
            _ = method.Overrides;
        }

        foreach (var property in type.Properties)
        {
            _ = property.GetMethod;
            setMethods[property] = property.SetMethod;
        }

        foreach (var evt in type.Events)
        {
            _ = evt.AddMethod;
            _ = evt.RemoveMethod;
        }
    }

    private static void PreloadCustomAttributes(ICustomAttributeProvider provider)
    {
        foreach (var attr in provider.CustomAttributes)
        {
            // Reading the arguments is relatively expensive since it requires
            // resolving the attribute constructor, so only do it for the
            // attributes where the arguments are actually used.
            switch (attr.AttributeType.FullName)
            {
                case "Windows.Foundation.Metadata.ActivatableAttribute":
                case "Windows.Foundation.Metadata.ComposableAttribute":
                case "Windows.Foundation.Metadata.StaticAttribute":
                case "Windows.Foundation.Metadata.OverloadAttribute":
                case "Windows.Foundation.Metadata.DeprecatedAttribute":
                    _ = attr.ConstructorArguments;
                    break;
            }
        }
    }
}
